		Assert.Equal(0, run.LevelledOrder(SpecialSlot.C), "T2: the replaced move's level-up went with it");
		Assert.Equal("test-spirit-wave", TargetId(run), "T2/T3: all Lv 1 again and nothing in a slot has levelled, so slot A");
	}

