  22 	/// one more than the highest stamp in any slot, so no two specials in a slot share a non-zero stamp.
  23 	/// Only the relative order matters; <see cref="LevelledOrder"/> is the public, canonical form.
  24 	/// </summary>
  25 	readonly int[] _levelledAt = new int[5];
