  29 	/// specials currently in a slot: 1 = the earliest of them, higher = more recent, 0 = it has not levelled
  30 	/// this run (or the slot is empty). It belongs to the special, not the slot: a replaced special's level-up
  31 	/// is dropped with it (T2). Part of <see cref="StateHash"/>; restored by <see cref="RestoreLevelledOrder"/>.
  32 	/// </summary>
  33 	public int LevelledOrder(SpecialSlot slot)
  34 	{
  35 		int at = _slots[(int)slot] is null ? 0 : _levelledAt[(int)slot];
  36 		if (at == 0) return 0;
  37 		int rank = 1;
  38 		for (int i = 1; i < _slots.Length; i++)
  39 			if (_slots[i] is not null && _levelledAt[i] > 0 && _levelledAt[i] < at) rank++;
