 173 		// special in a slot has levelled keeps the hash it had before the copy rule (recorded replays).
 174 		bool anyLevelled = false;
 175 		for (int i = 1; i < _slots.Length; i++) anyLevelled |= LevelledOrder((SpecialSlot)i) > 0;
 176 		if (anyLevelled)
 177 			for (int i = 1; i < _slots.Length; i++) h = Fnv.Mix(h, LevelledOrder((SpecialSlot)i));
 178 		if (Map is not null) // a run without a map keeps the hash it had before YOK-76 (recorded replays)
 179 		{
 180 			ulong m = Map.StateHash();
