  29 		string json = "{\"kind\":\"special\",\"id\":\"" + id + "\",\"input\":{\"kata\":{\"slot\":\"" + slot + "\"}},\"levels\":{" + levels + "}}";
  30 		return SpecialLoader.Parse(json);
  31 	}
  32 
  33 	static string TargetId(RunState run) => CopyRule.Target(run)?.Data.Id ?? "(none)";
  34 
  35 	static string Orders(RunState run) =>
  36 		$"{run.LevelledOrder(SpecialSlot.A)},{run.LevelledOrder(SpecialSlot.B)},{run.LevelledOrder(SpecialSlot.C)},{run.LevelledOrder(SpecialSlot.D)}";
  37 
  38 	static bool Rejects(RunState run, int a, int b, int c, int d)
  39 	{
  40 		try { run.RestoreLevelledOrder(a, b, c, d); }
  41 		catch (ArgumentException) { return true; }
  42 		return false;
  43 	}
