	// --- NEW: Foxfire in slot C, both schemes (A3, K3) -----------------------------------------

	[Test]
	public static void NewFoxfireFiresFromSlotCInKataAndKihon()
	{
		var pool = Pool();
		var run = RunState.NewRun(pool);
		var d = RewardDraft.Build(run, pool, "kitsune", 3);
